#[unsafe(no_mangle)]
pub extern "C" fn dw1_collision_camera_flag_byte(byte_index: i32) -> u8 {
    // SAFETY: valid C-owned resident static, generated native layout, fixed-width u32.
    // Copy the scalar: a native pointer/padding byte must never masquerade as PS1 data.
    let flag = unsafe { (&raw const STDVS_CAMERA.coord.flg).read_volatile() };
    flag_byte(flag, byte_index).unwrap_or_else(|| {
        psyq::trap::unimplemented("native limit: invalid STDVS_CAMERA.coord.flg byte selector")
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn flag_is_little_endian_not_a_cached_or_default_zero_value() {
        for value in [0, 1, 0x11223344, 0x00800000, 0xff017f80, u32::MAX] {
            for byte in 0..4 {
                assert_eq!(
                    flag_byte(value, byte),
                    Some(((value >> (byte * 8)) & 255) as u8)
                );
            }
        }
        assert_eq!(flag_byte(0, 2), Some(0));
        assert_eq!(flag_byte(0x00550000, 2), Some(0x55));
        assert_eq!(flag_byte(0x00800000, 2), Some(0x80));
    }
    #[test]
    fn selectors_outside_the_one_word_are_rejected() {
        for i in [i32::MIN, -5, -1, 4, 5, 36, 40, i32::MAX] {
            assert_eq!(flag_byte(u32::MAX, i), None);
        }
    }
    #[test]
    fn generated_native_layout_is_not_the_ps1_byte_offset() {
        use core::mem::{offset_of, size_of};
        assert_eq!(size_of::<c::StdVsCamera>(), 160);
        assert_eq!(
            offset_of!(c::StdVsCamera, coord) + offset_of!(c::GsCOORDINATE2, flg),
            40
        );
        assert_ne!(offset_of!(c::StdVsCamera, coord), 36);
    }
}
